import * as T from './vendor/three.module.js';
import {createPlayerHand} from './player-hand.js';
export function createRobotGreeting({robot,camera,stopSpeech=()=>{}}){
 const start=robot.position.clone(),rotation=robot.quaternion.clone(),cameraRotation=camera.quaternion.clone(),hand=createPlayerHand(T,camera);hand.g.scale.setScalar(.8);
 // Replace the old rigid right arm with shoulder, elbow, wrist and fingers.
 for(const part of [...robot.children])if(part.isMesh&&part.position.x>=-.45&&part.position.x<=-.35&&part.position.y>=.47&&part.position.y<=1.5){robot.remove(part);part.geometry?.dispose();part.material?.dispose();}
 const arm=new T.Group();arm.name='Robot articulated handshake arm';robot.add(arm);const metal=new T.MeshStandardMaterial({color:0x899d98,metalness:.65,roughness:.32}),dark=new T.MeshStandardMaterial({color:0x354d50,metalness:.5,roughness:.45});
 const upper=new T.Mesh(new T.CylinderGeometry(.065,.07,1,14),metal),forearm=new T.Mesh(new T.CylinderGeometry(.06,.065,1,14),metal),elbow=new T.Mesh(new T.SphereGeometry(.085,16,12),dark),palm=new T.Group();palm.name='Robot offered palm';arm.add(upper,forearm,elbow,palm);const block=new T.Mesh(new T.BoxGeometry(.15,.09,.16),metal);palm.add(block);for(let i=0;i<4;i++){const finger=new T.Mesh(new T.BoxGeometry(.025,.045,.09),dark);finger.position.set((i-1.5)*.035,-.015,.105);palm.add(finger);}const thumb=new T.Mesh(new T.BoxGeometry(.035,.065,.08),metal);thumb.position.set(-.095,-.005,.02);thumb.rotation.z=.5;palm.add(thumb);
 const legs=robot.children.filter(o=>o.isMesh&&Math.abs(Math.abs(o.position.x)-.18)<.001&&Math.abs(o.position.y-.4)<.001);let time=0,state='approaching',contact=new T.Vector3();const up=new T.Vector3(0,1,0),shoulder=new T.Vector3(-.4,1.45,0),restElbow=new T.Vector3(-.4,1.02,0),restWrist=new T.Vector3(-.4,.63,0);
 const ease=u=>{u=T.MathUtils.clamp(u,0,1);return u*u*(3-2*u);};
 function bone(mesh,a,b){mesh.position.copy(a).add(b).multiplyScalar(.5);mesh.scale.y=a.distanceTo(b);mesh.quaternion.setFromUnitVectors(up,b.clone().sub(a).normalize());}
 function armPose(amount,bob=0){robot.updateMatrixWorld(true);const wrist=restWrist.clone().lerp(robot.worldToLocal(contact.clone()),amount),joint=restElbow.clone().lerp(new T.Vector3(-.48,1.16,.28),amount);joint.y+=bob*.5;bone(upper,shoulder,joint);bone(forearm,joint,wrist);elbow.position.copy(joint);palm.position.copy(wrist);palm.rotation.x=-amount*.1;}
 function finish(){state='done';robot.position.copy(start);robot.quaternion.copy(rotation);legs.forEach(l=>l.rotation.x=0);hand.reset();camera.quaternion.copy(cameraRotation);armPose(0);}
 function update(dt){if(state==='done')return false;time+=dt;const approach=ease(time/1),returning=ease((time-3.2)/1.4),near=new T.Vector3(-.45,0,3.8);robot.position.copy(start).lerp(near,approach).lerp(start,returning);const moving=time<1||time>3.2;robot.position.y=moving?Math.abs(Math.sin(time*11))*.018:0;for(let i=0;i<legs.length;i++)legs[i].rotation.x=moving?Math.sin(time*11+i*Math.PI)*.25:0;robot.lookAt(camera.position.x,robot.position.y,camera.position.z);camera.lookAt(robot.position.x,1.4,robot.position.z);const reach=ease((time-1)/.5)*(1-ease((time-2.8)/.4)),bob=time>1.5&&time<2.8?Math.sin((time-1.5)*11)*.035:0;contact.set(-.18,1.13+bob,4.33);armPose(reach,bob);if(reach>0){camera.updateMatrixWorld(true);const local=camera.worldToLocal(contact.clone());hand.grip(.65);hand.g.position.copy(new T.Vector3(.22,-.45,-.6)).lerp(local.add(new T.Vector3(0,-.096,.028)),reach);}else hand.reset();state=time<1?'approaching':time<1.5?'offering':time<2.8?'shaking':time<3.2?'releasing':'returning';document.getElementById('intro-task').textContent=time<1.5?'הרובוט ניגש לברך אותך':'ברוך הבא למעבדה • לחיצת יד';document.getElementById('intro-prompt').textContent=(matchMedia('(pointer:coarse)').matches?'פעולה':'E')+' • להמשיך';if(time>=4.6)finish();return true;}
 armPose(0);return{update,skip(){stopSpeech();finish();},dispose(){finish();hand.g.removeFromParent();},get active(){return state!=='done';},get state(){return state;},get palm(){return palm;},get playerHand(){return hand.g;},get contact(){return contact.clone();}};
}
